const input = $input.first().json || {};
const by_status = input.by_status || {};
const changed = input.changed_24h || [];
const upcoming = input.upcoming || [];
const parts = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Jakarta', day: 'numeric', month: 'numeric' }).formatToParts(new Date());
let d = 1, m = 1;
for (const p of parts) { if (p.type === 'day') d = Number(p.value); if (p.type === 'month') m = Number(p.value); }
const months = ['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'];
const dateStr = d + ' ' + (months[m - 1] || '');
const order = ['Applied','Screening','HR Interview','Technical Interview','Offer','Accepted','Rejected','Withdrawn','Ghosted'];
const pairs = [];
for (const s of order) { const n = Number(by_status[s] || 0); if (n > 0) pairs.push(s + ' ' + n); }
const lines = [];
lines.push('☀️ Rekap lamaran (' + dateStr + ')');
lines.push(pairs.length ? 'Aktif: ' + pairs.join(' · ') : 'Belum ada lamaran tercatat.');
if (changed.length) lines.push('Berubah 24 jam: ' + changed.map((c) => (c.company_name || '') + ' – ' + (c.role_title || '') + ' → ' + (c.status || '')).join('; '));
if (upcoming.length) lines.push('Deadline dekat: ' + upcoming.map((u) => (u.company_name || '') + ' – ' + (u.role_title || '') + ' (' + (u.kind || '') + ': ' + (u.date || '') + ')').join('; '));
return [{ json: { message: lines.join('\n') } }];
